from __future__ import annotations
import base64, zlib
from pathlib import Path

ROOT=Path(__file__).resolve().parent.parent/"src"
TRANS=''
REPLS=[
    ('from .transcriber import TranscriptionWorker\n', 'from .transcriber import DEFAULT_HOTWORDS, TranscriptionWorker\n'),
    ('        self.chunk_seconds.setValue(8)\n', '        self.chunk_seconds.setValue(12)\n'),
    ('        self.chunk_seconds.setSuffix(" сек")\n', '        self.chunk_seconds.setSuffix(" сек")\n        self.chunk_seconds.setToolTip("12 секунд — профиль повышенной точности: больше контекста, но чуть выше задержка вывода.")\n'),
    ('        settings.addRow(model_row)\n\n        diarization_row = QWidget()\n', '        settings.addRow(model_row)\n\n        self.hotwords_edit = QLineEdit(DEFAULT_HOTWORDS)\n        self.hotwords_edit.setToolTip(\n            "Слова и названия через запятую. Они подсказывают Whisper правильное написание терминов, ФИО и систем."\n        )\n        settings.addRow("Словарь:", self.hotwords_edit)\n\n        self.use_context = QCheckBox("Использовать контекст предыдущих реплик")\n        self.use_context.setChecked(True)\n        self.use_context.setToolTip(\n            "Помогает сохранять смысл и написание терминов между соседними аудиофрагментами. "\n            "Контекст хранится только в памяти программы."\n        )\n        settings.addRow("", self.use_context)\n\n        quality_hint = QLabel(\n            "Режим 0.6 Quality: Whisper small + beam search 5 + VAD с защитой коротких слов + "\n            "контекст + словарь терминов. Для лучшего качества добавьте сюда фамилии участников и названия систем."\n        )\n        quality_hint.setWordWrap(True)\n        settings.addRow("", quality_hint)\n\n        diarization_row = QWidget()\n'),
    ('                "chunk_seconds": int(self.chunk_seconds.value()),\n                "speaker_identification": bool(speaker_model_path),\n', '                "chunk_seconds": int(self.chunk_seconds.value()),\n                "recognition_profile": "quality-v0.6",\n                "beam_size": 5,\n                "context_enabled": self.use_context.isChecked(),\n                "hotwords_count": len([x for x in self.hotwords_edit.text().split(",") if x.strip()]),\n                "speaker_identification": bool(speaker_model_path),\n'),
    ('            speaker_threshold=float(self.speaker_threshold.value()),\n            on_entry=self.bus.transcript.emit,\n', '            speaker_threshold=float(self.speaker_threshold.value()),\n            hotwords=self.hotwords_edit.text(),\n            use_context=self.use_context.isChecked(),\n            beam_size=5,\n            on_entry=self.bus.transcript.emit,\n'),
    ('            self.model_edit,\n            self.chunk_seconds,\n            self.enable_diarization,\n', '            self.model_edit,\n            self.chunk_seconds,\n            self.hotwords_edit,\n            self.use_context,\n            self.enable_diarization,\n'),
    ('self.statusBar().showMessage(f"Захват аудио запущен ({mode}). Ожидается первая расшифровка…")', 'self.statusBar().showMessage(f"Захват аудио запущен ({mode}, Quality). Ожидается первая расшифровка…")'),
]

def main():
    (ROOT/"app"/"transcriber.py").write_bytes(zlib.decompress(base64.b64decode(TRANS)))
    ui=ROOT/"app"/"ui.py"
    text=ui.read_text(encoding="utf-8")
    for old,new in REPLS:
        if old not in text: raise RuntimeError(f"missing patch fragment: {old[:60]!r}")
        text=text.replace(old,new,1)
    ui.write_text(text,encoding="utf-8")
    hp=ROOT/"app"/"health.py"
    h=hp.read_text(encoding="utf-8").replace('APP_VERSION = "0.5.1"','APP_VERSION = "0.6.0"')
    hp.write_text(h,encoding="utf-8")
    (ROOT/"app"/"__init__.py").write_text('__version__ = "0.6.0"\n',encoding="utf-8")
    print("Quality patch 0.6 applied")

if __name__=="__main__": main()
